def sum_imbalance_numbers(nums: List[int]) -> int:
    total_sum = 0
    unique_nums = list(set(nums))
    for x, y in combinations(unique_nums, 2):
        if y - x <= 1:
            continue
        allowed = []
        for num in nums:
            if num <= x or num >= y:
                allowed.append(True)
            else:
                allowed.append(False)
        segments = []
        current_segment = []
