def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    if n < 2 * k:
        return float('inf')

    def compute_cost(sub):
        L = len(sub)
        if L < 2:
            return 0
        min_cost = float('inf')
        divisors = []
        for d in range(1, L):
            if L % d == 0:
                divisors.append(d)
        for d in divisors:
            total = 0
            for r in range(d):
                group = []
                for i in range(r, L, d):
                    group.append(sub[i])
                m_group = len(group)
                cost_group = 0
                for i in range(m_group // 2):
                    if group[i] != group[m_group - 1 - i]:
                        cost_group += 1
                total += cost_group
            if total < min_cost:
                min_cost = total
        return min_cost

    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(k, i // 2) + 1):
            if j == 1:
                if i >= 2:
                    cost_val = compute_cost(s[:i])
                    dp[i][j] = cost_val
                else:
                    dp[i][j] = float('inf')
            else:
                for m in range(2 * (j - 1), i - 1):
                    if dp[m][j - 1] == float('inf'):
                        continue
                    current_sub = s[m:i]
                    cost_val = compute_cost(current_sub)
                    if dp[m][j - 1] + cost_val < dp[i][j]:
                        dp[i][j] = dp[m][j - 1] + cost_val

    return dp[n][k] if dp[n][k] != float('inf') else 0
```

