MOD = 998244353

def count_arithmetic_subsequences(n: int, a: List[int]) -> List[int]:
    if n == 0:
        return []
    total = [0] * (n + 2)
    total[1] = n % MOD
    if n == 1:
        return [total[1] % MOD]

    dp = [dict() for _ in range(n)]

    for j in range(1, n):
        for i in range(j):
            d = a[j] - a[i]
            total[2] = (total[2] + 1) % MOD
            if d not in dp[j]:
                dp[j][d] = {}
            dp[j][d][2] = dp[j][d].get(2, 0) + 1

            if d in dp[i]:
                for l, cnt in dp[i][d].items():
                    new_len = l + 1
                    total[new_len] = (total[new_len] + cnt) % MOD
                    if new_len not in dp[j][d]:
                        dp[j][d][new_len] = 0
                    dp[j][d][new_len] = (dp[j][d][new_len] + cnt) % MOD

    result = []
    for k in range(1, n + 1):
        result.append(total[k] % MOD)
    return result
