def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    def min_changes(t):
        n_t = len(t)
        if n_t < 2:
            return float('inf')
        min_cost = float('inf')
        for d in range(1, n_t):
            if n_t % d == 0:
                cost = 0
                for r in range(d):
                    m = (n_t - r + d - 1) // d
                    for i in range(m // 2):
                        idx1 = r + i * d
                        idx2 = r + (m - 1 - i) * d
                        if t[idx1] != t[idx2]:
                            cost += 1
                if cost < min_cost:
                    min_cost = cost
        return min_cost if min_cost != float('inf') else float('inf')

    n = len(s)
    cost_matrix = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            substring = s[i:j]
            cost_matrix[i][j] = min_changes(substring)

    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if i < 2 * j:
                dp[i][j] = float('inf')
                continue
            for m in range(2 * (j - 1), i):
                current_cost = cost_matrix[m][i]
                if dp[m][j - 1] + current_cost < dp[i][j]:
                    dp[i][j] = dp[m][j - 1] + current_cost

    return dp[n][k] if dp[n][k] != float('inf') else 0
