                shipping_day = max_order_day
                total_diss = shipping_day * batch_size - (prefix[i + 1] - prefix[j])
                total = prev_dp[-1] + total_diss
                if shipping_day in current_dp:
                    current_dp[shipping_day] = min(current_dp[shipping_day], total)
