import math
from typing import List

def kth_smallest_amount(coins: List[int], k: int) -> int:
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    def count(x):
        n = len(coins)
        total = 0
        for mask in range(1, 1 << n):
            bits = bin(mask).count('1')
            current_lcm = 1
            for i in range(n):
                if mask & (1 << i):
                    current_lcm = lcm(current_lcm, coins[i])
                    if current_lcm > x:
                        break
            else:
                sign = (-1) ** (bits + 1)
                total += sign * (x // current_lcm)
        return total

    if not coins:
        return 0

    low, high = 1, max(coins) * k

    while low < high:
        mid = (low + high) // 2
        c = count(mid)
        if c < k:
            low = mid + 1
        else:
            high = mid

    return low
